
import matplotlib.pyplot as plt
from pathlib import Path as path
import numpy as np


# ============================================================
# FILESYSTEM CONFIGURATION
# ============================================================

# Resolve the directory containing this script.
folder = path(__file__).resolve().parent

# Locate the CSV generated by the C++ sensitivity experiment.
csv_path = folder / "sensitivity.csv"


# ============================================================
# DATA VALIDATION
# ============================================================

# Display filesystem information to help diagnose
# missing or incorrectly located experimental datasets.
print("Python script folder:", folder)
print("CSV path being checked:", csv_path)
print("Does the file exist?", csv_path.exists())

print("CSV files in this folder:")

for f in folder.glob("*.csv"):
    print(" -", repr(f.name))


# ============================================================
# DATA IMPORT
# ============================================================

# Load the experimental data, skipping the CSV header.
data = np.loadtxt(
    csv_path,
    delimiter=",",
    skiprows=1
)


# Extract the individual columns.
iteration = data[:, 0]

state_a = data[:, 1]
state_b = data[:, 2]

difference = data[:, 3]


# ============================================================
# SENSITIVITY ANALYSIS
# ============================================================

# Create two vertically arranged plotting regions:
#
# 1. Comparison of the two trajectories.
# 2. Evolution of their absolute separation.
#
fig, axes = plt.subplots(
    2,
    1,
    figsize=(11, 8)
)


# ------------------------------------------------------------
# TRAJECTORY COMPARISON
# ------------------------------------------------------------

# Plot the evolution of both initial conditions.
#
# The trajectories begin very close to one another.
# Their subsequent evolution illustrates the sensitivity
# of the logistic map to small initial differences.

axes[0].plot(
    iteration,
    state_a,
    label="Initial x0 = 0.2"
)

axes[0].plot(
    iteration,
    state_b,
    label="Initial x0 = 0.200001"
)

axes[0].set_title(
    "Logistic Map: Two Nearby Initial Conditions"
)

axes[0].set_xlabel("Iteration")
axes[0].set_ylabel("State x")

axes[0].legend()
axes[0].grid(alpha=0.3)


# ------------------------------------------------------------
# TRAJECTORY SEPARATION
# ------------------------------------------------------------

# Plot the absolute difference between the two trajectories:
#
# Δ_n = |x_n(a) - x_n(b)|
#
# A logarithmic vertical scale allows small and large
# differences to be examined within the same figure.
#
# np.maximum prevents zero-valued differences from
# causing issues when represented on a logarithmic axis.

axes[1].semilogy(
    iteration,
    np.maximum(difference, 1e-18)
)

axes[1].set_title(
    "Separation Between Trajectories"
)

axes[1].set_xlabel("Iteration")
axes[1].set_ylabel("Absolute difference (log scale)")

axes[1].grid(alpha=0.3)


# ============================================================
# OUTPUT
# ============================================================

plt.tight_layout()

# Save the resulting figure in the current working directory.
plt.savefig(
    folder / "sensitivity.png",
    dpi=200
)

# Display the visualisation.
plt.show()
